USE [JamunaBankProcurement];
GO
/* Normalize and repair Concern Division workflows created by older procedure versions. */
UPDATE w SET w.CURRENT_OWNER_TYPE='ORG_UNIT',w.CURRENT_OWNER_EMPLOYEE_ID=NULL,w.CURRENT_OWNER_ORG_UNIT_ID=s.ORG_UNIT_ID,w.CURRENT_STATUS='PENDING',w.MODIFIED_DATE=SYSUTCDATETIME()
FROM dbo.WORKFLOW_INSTANCE w JOIN dbo.WORKFLOW_RULE r ON r.WORKFLOW_RULE_ID=w.WORKFLOW_RULE_ID JOIN dbo.CONCERN_DIVISION_SETUP s ON s.CONCERN_DIVISION_ID=r.CONCERN_DIVISION_ID AND s.IS_ACTIVE=1 JOIN dbo.REQUISITION_HEADER h ON h.REQUISITION_ID=w.REQUISITION_ID AND h.CURRENT_STATUS='IN_WORKFLOW' AND h.IS_ACTIVE=1
WHERE w.CURRENT_STAGE='CONCERN_DIVISION' AND w.COMPLETED_DATE IS NULL AND(w.CURRENT_STATUS<>'PENDING' OR w.CURRENT_OWNER_TYPE<>'ORG_UNIT' OR w.CURRENT_OWNER_ORG_UNIT_ID IS NULL OR w.CURRENT_OWNER_ORG_UNIT_ID<>s.ORG_UNIT_ID OR w.CURRENT_OWNER_EMPLOYEE_ID IS NOT NULL);
UPDATE a SET a.IS_CURRENT=0,a.RELEASED_DATE=SYSUTCDATETIME()
FROM dbo.REQUISITION_ASSIGNMENT a JOIN dbo.WORKFLOW_INSTANCE w ON w.REQUISITION_ID=a.REQUISITION_ID JOIN dbo.WORKFLOW_RULE r ON r.WORKFLOW_RULE_ID=w.WORKFLOW_RULE_ID JOIN dbo.CONCERN_DIVISION_SETUP s ON s.CONCERN_DIVISION_ID=r.CONCERN_DIVISION_ID AND s.IS_ACTIVE=1
WHERE w.CURRENT_STAGE='CONCERN_DIVISION' AND w.CURRENT_STATUS='PENDING' AND w.COMPLETED_DATE IS NULL AND a.IS_CURRENT=1 AND(a.ASSIGNMENT_TYPE<>'CONCERN_OFFICIAL' OR a.ASSIGNED_TO_ORG_UNIT_ID IS NULL OR a.ASSIGNED_TO_ORG_UNIT_ID<>s.ORG_UNIT_ID);
INSERT dbo.REQUISITION_ASSIGNMENT(REQUISITION_ID,ASSIGNMENT_TYPE,ASSIGNED_TO_ORG_UNIT_ID,CREATED_BY)
SELECT w.REQUISITION_ID,'CONCERN_OFFICIAL',s.ORG_UNIT_ID,'workflow-assignment-repair' FROM dbo.WORKFLOW_INSTANCE w JOIN dbo.WORKFLOW_RULE r ON r.WORKFLOW_RULE_ID=w.WORKFLOW_RULE_ID JOIN dbo.CONCERN_DIVISION_SETUP s ON s.CONCERN_DIVISION_ID=r.CONCERN_DIVISION_ID AND s.IS_ACTIVE=1 JOIN dbo.REQUISITION_HEADER h ON h.REQUISITION_ID=w.REQUISITION_ID AND h.CURRENT_STATUS='IN_WORKFLOW' AND h.IS_ACTIVE=1
WHERE w.CURRENT_STAGE='CONCERN_DIVISION' AND w.CURRENT_STATUS='PENDING' AND w.COMPLETED_DATE IS NULL AND NOT EXISTS(SELECT 1 FROM dbo.REQUISITION_ASSIGNMENT a WHERE a.REQUISITION_ID=w.REQUISITION_ID AND a.ASSIGNMENT_TYPE='CONCERN_OFFICIAL' AND a.ASSIGNED_TO_ORG_UNIT_ID=s.ORG_UNIT_ID AND a.IS_CURRENT=1);
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernDivision_GetDetail @RequisitionId BIGINT,@EmployeeId VARCHAR(30) AS BEGIN SET NOCOUNT ON;DECLARE @requester VARCHAR(30);SELECT @requester=h.REQUESTED_BY_EMPLOYEE_ID FROM dbo.REQUISITION_HEADER h JOIN dbo.WORKFLOW_INSTANCE w ON w.REQUISITION_ID=h.REQUISITION_ID JOIN dbo.WORKFLOW_RULE r ON r.WORKFLOW_RULE_ID=w.WORKFLOW_RULE_ID JOIN dbo.CONCERN_DIVISION_OFFICIAL o ON o.CONCERN_DIVISION_ID=r.CONCERN_DIVISION_ID AND o.EMPLOYEE_ID=@EmployeeId AND o.IS_ACTIVE=1 WHERE h.REQUISITION_ID=@RequisitionId AND h.CURRENT_STATUS='IN_WORKFLOW'AND w.CURRENT_STAGE='CONCERN_DIVISION'AND w.CURRENT_STATUS='PENDING'AND w.COMPLETED_DATE IS NULL;IF @requester IS NULL BEGIN SELECT TOP(0) REQUISITION_ID,REQUISITION_NO,REQUESTED_BY_EMPLOYEE_ID,REQUESTED_ORG_UNIT_ID,CAST(''AS NVARCHAR(200))ORG_UNIT_NAME,REQUESTED_DATE,JUSTIFICATION,TOTAL_ESTIMATED_AMOUNT,CURRENT_STATUS FROM dbo.REQUISITION_HEADER;RETURN;END;EXEC dbo.usp_Requisition_GetMakerDetail @RequisitionId,@requester;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernDivision_GetReviewContext @RequisitionId BIGINT,@EmployeeId VARCHAR(30) AS BEGIN SET NOCOUNT ON;SELECT r.WORKFLOW_RULE_ID,r.RULE_CODE,r.RULE_NAME,w.CURRENT_STAGE,r.DESTINATION_AFTER_CONCERN MATRIX_DESTINATION,d.CONCERN_DIVISION_ID,o.ORG_UNIT_NAME CONCERN_DIVISION_NAME FROM dbo.WORKFLOW_INSTANCE w JOIN dbo.WORKFLOW_RULE r ON r.WORKFLOW_RULE_ID=w.WORKFLOW_RULE_ID JOIN dbo.CONCERN_DIVISION_SETUP d ON d.CONCERN_DIVISION_ID=r.CONCERN_DIVISION_ID JOIN dbo.ORG_UNIT o ON o.ORG_UNIT_ID=d.ORG_UNIT_ID JOIN dbo.CONCERN_DIVISION_OFFICIAL f ON f.CONCERN_DIVISION_ID=d.CONCERN_DIVISION_ID AND f.EMPLOYEE_ID=@EmployeeId AND f.IS_ACTIVE=1 WHERE w.REQUISITION_ID=@RequisitionId AND w.CURRENT_STAGE='CONCERN_DIVISION'AND w.CURRENT_STATUS='PENDING'AND w.COMPLETED_DATE IS NULL;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernDivision_GetPending @EmployeeId VARCHAR(30) AS BEGIN SET NOCOUNT ON;SELECT h.REQUISITION_ID,h.REQUISITION_NO,h.REQUESTED_DATE,h.TOTAL_ESTIMATED_AMOUNT,r.CONCERN_DIVISION_ID,ou.ORG_UNIT_NAME CONCERN_DIVISION_NAME,u.DISPLAY_NAME REQUESTED_BY_NAME,(SELECT COUNT(*)FROM dbo.REQUISITION_ITEM i WHERE i.REQUISITION_ID=h.REQUISITION_ID AND i.IS_ACTIVE=1)ITEM_COUNT FROM dbo.WORKFLOW_INSTANCE w JOIN dbo.REQUISITION_HEADER h ON h.REQUISITION_ID=w.REQUISITION_ID JOIN dbo.WORKFLOW_RULE r ON r.WORKFLOW_RULE_ID=w.WORKFLOW_RULE_ID JOIN dbo.CONCERN_DIVISION_SETUP s ON s.CONCERN_DIVISION_ID=r.CONCERN_DIVISION_ID JOIN dbo.ORG_UNIT ou ON ou.ORG_UNIT_ID=s.ORG_UNIT_ID JOIN dbo.APP_USER_CACHE u ON u.EMPLOYEE_ID=h.REQUESTED_BY_EMPLOYEE_ID JOIN dbo.CONCERN_DIVISION_OFFICIAL o ON o.CONCERN_DIVISION_ID=r.CONCERN_DIVISION_ID AND o.EMPLOYEE_ID=@EmployeeId AND o.IS_ACTIVE=1 WHERE w.CURRENT_STAGE='CONCERN_DIVISION'AND w.CURRENT_STATUS='PENDING'AND w.COMPLETED_DATE IS NULL AND h.CURRENT_STATUS='IN_WORKFLOW'AND h.IS_ACTIVE=1 ORDER BY h.REQUESTED_DATE;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernDivision_VerifyComplete @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000)=NULL,@BatchReferenceId UNIQUEIDENTIFIER=NULL AS BEGIN SET NOCOUNT ON;DECLARE @next VARCHAR(40);SELECT @next=r.DESTINATION_AFTER_CONCERN FROM dbo.WORKFLOW_INSTANCE w JOIN dbo.WORKFLOW_RULE r ON r.WORKFLOW_RULE_ID=w.WORKFLOW_RULE_ID WHERE w.REQUISITION_ID=@RequisitionId AND w.CURRENT_STAGE='CONCERN_DIVISION'AND w.COMPLETED_DATE IS NULL;IF @next NOT IN('READY_FOR_PROCUREMENT','PROCUREMENT_AUTHORITY')BEGIN SELECT'004'RESULT_CODE,N'No valid matrix-defined destination exists after Concern processing.'RESULT_MESSAGE,@RequisitionId ENTITY_ID,NULL REFERENCE_NO;RETURN;END;DECLARE @result TABLE(RESULT_CODE VARCHAR(3),RESULT_MESSAGE NVARCHAR(4000),ENTITY_ID BIGINT,REFERENCE_NO VARCHAR(100));INSERT @result EXEC dbo.usp_Workflow_Advance @RequisitionId,@ActorEmployeeId,'CONCERN_DIVISION','CONCERN_VERIFY_COMPLETE','CONCERN_OFFICIAL',@next,@Remarks,@BatchReferenceId;SELECT RESULT_CODE,RESULT_MESSAGE,ENTITY_ID,CASE WHEN RESULT_CODE='000'THEN @next ELSE REFERENCE_NO END REFERENCE_NO FROM @result;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernDivision_ForwardToAuthority @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000)=NULL,@BatchReferenceId UNIQUEIDENTIFIER=NULL AS BEGIN SET NOCOUNT ON;IF NOT EXISTS(SELECT 1 FROM dbo.WORKFLOW_INSTANCE w JOIN dbo.WORKFLOW_RULE r ON r.WORKFLOW_RULE_ID=w.WORKFLOW_RULE_ID JOIN dbo.CONCERN_DIVISION_AUTHORITY a ON a.CONCERN_DIVISION_ID=r.CONCERN_DIVISION_ID AND a.IS_ACTIVE=1 WHERE w.REQUISITION_ID=@RequisitionId AND w.CURRENT_STAGE='CONCERN_DIVISION'AND w.COMPLETED_DATE IS NULL)BEGIN SELECT'001'RESULT_CODE,N'No active authority is configured for this Concern Division.'RESULT_MESSAGE,@RequisitionId ENTITY_ID,NULL REFERENCE_NO;RETURN;END;DECLARE @result TABLE(RESULT_CODE VARCHAR(3),RESULT_MESSAGE NVARCHAR(4000),ENTITY_ID BIGINT,REFERENCE_NO VARCHAR(100));INSERT @result EXEC dbo.usp_Workflow_Advance @RequisitionId,@ActorEmployeeId,'CONCERN_DIVISION','CONCERN_FORWARD_TO_AUTHORITY','CONCERN_OFFICIAL','CONCERN_AUTHORITY',@Remarks,@BatchReferenceId;SELECT RESULT_CODE,RESULT_MESSAGE,ENTITY_ID,CASE WHEN RESULT_CODE='000'THEN'CONCERN_AUTHORITY'ELSE REFERENCE_NO END REFERENCE_NO FROM @result;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernDivision_Return @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000),@BatchReferenceId UNIQUEIDENTIFIER=NULL AS BEGIN SET NOCOUNT ON;IF NULLIF(LTRIM(RTRIM(@Remarks)),'')IS NULL BEGIN SELECT'001'RESULT_CODE,N'Remarks are required.'RESULT_MESSAGE,@RequisitionId ENTITY_ID,NULL REFERENCE_NO;RETURN;END;EXEC dbo.usp_Workflow_SimpleTerminal @RequisitionId,@ActorEmployeeId,'CONCERN_OFFICIAL','IN_WORKFLOW','CONCERN_RETURN','RETURNED','PROCUREMENT_OFFICER',@Remarks,@BatchReferenceId;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernDivision_NotRecommend @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000),@BatchReferenceId UNIQUEIDENTIFIER=NULL AS BEGIN SET NOCOUNT ON;IF NULLIF(LTRIM(RTRIM(@Remarks)),'')IS NULL BEGIN SELECT'001'RESULT_CODE,N'Remarks are required.'RESULT_MESSAGE,@RequisitionId ENTITY_ID,NULL REFERENCE_NO;RETURN;END;EXEC dbo.usp_Workflow_SimpleTerminal @RequisitionId,@ActorEmployeeId,'CONCERN_OFFICIAL','IN_WORKFLOW','CONCERN_NOT_RECOMMEND','NOT_RECOMMENDED','END',@Remarks,@BatchReferenceId;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernDivision_GetAll @EmployeeId VARCHAR(30),@RequisitionNo VARCHAR(30)=NULL,@AssetId BIGINT=NULL,@RequisitionType VARCHAR(20)=NULL,@Status VARCHAR(40)=NULL,@FromDate DATE=NULL,@ToDate DATE=NULL
AS BEGIN
 SET NOCOUNT ON;
 SELECT h.REQUISITION_ID,h.REQUISITION_NO,h.REQUESTED_DATE,h.REQUESTED_BY_EMPLOYEE_ID,COALESCE(u.DISPLAY_NAME,h.REQUESTED_BY_EMPLOYEE_ID)REQUESTED_BY_NAME,org.ORG_UNIT_NAME,
  COALESCE((SELECT STRING_AGG(CONVERT(NVARCHAR(MAX),x.ITEM_NAME_SNAPSHOT),', ')FROM(SELECT DISTINCT i.ITEM_NAME_SNAPSHOT FROM dbo.REQUISITION_ITEM i WHERE i.REQUISITION_ID=h.REQUISITION_ID AND i.IS_ACTIVE=1)x),'')ASSETS,
  COALESCE((SELECT STRING_AGG(CONVERT(NVARCHAR(MAX),x.REQ_TYPE),', ')FROM(SELECT DISTINCT i.REQ_TYPE FROM dbo.REQUISITION_ITEM i WHERE i.REQUISITION_ID=h.REQUISITION_ID AND i.IS_ACTIVE=1)x),'')REQUISITION_TYPES,
  COALESCE((SELECT SUM(i.QUANTITY)FROM dbo.REQUISITION_ITEM i WHERE i.REQUISITION_ID=h.REQUISITION_ID AND i.IS_ACTIVE=1),0)TOTAL_QUANTITY,h.TOTAL_ESTIMATED_AMOUNT,h.CURRENT_STATUS,
  w.CURRENT_STAGE PENDING_STAGE,
  CASE WHEN a.ASSIGNED_TO_EMPLOYEE_ID IS NOT NULL THEN COALESCE(au.DISPLAY_NAME,a.ASSIGNED_TO_EMPLOYEE_ID)WHEN a.ASSIGNMENT_TYPE='MANAGER'THEN CONCAT('Branch Manager Pool - ',org.ORG_UNIT_NAME)WHEN a.ASSIGNMENT_TYPE='PROCUREMENT_OFFICER_POOL'THEN'Procurement Officer Pool'WHEN a.ASSIGNMENT_TYPE='CONCERN_OFFICIAL'THEN'Concern Official Pool'WHEN a.ASSIGNMENT_TYPE='CONCERN_AUTHORITY'THEN'Concern Division Authority Pool'WHEN a.ASSIGNMENT_TYPE='PROCUREMENT_AUTHORITY_POOL'THEN'Procurement Authority Pool'WHEN a.ASSIGNMENT_TYPE='MAKER'THEN'Maker'ELSE NULL END PENDING_WITH
 FROM dbo.REQUISITION_HEADER h JOIN dbo.ORG_UNIT org ON org.ORG_UNIT_ID=h.REQUESTED_ORG_UNIT_ID LEFT JOIN dbo.APP_USER_CACHE u ON u.EMPLOYEE_ID=h.REQUESTED_BY_EMPLOYEE_ID
 LEFT JOIN dbo.WORKFLOW_INSTANCE w ON w.REQUISITION_ID=h.REQUISITION_ID AND w.COMPLETED_DATE IS NULL
 OUTER APPLY(SELECT TOP(1)x.ASSIGNMENT_TYPE,x.ASSIGNED_TO_EMPLOYEE_ID FROM dbo.REQUISITION_ASSIGNMENT x WHERE x.REQUISITION_ID=h.REQUISITION_ID AND x.IS_CURRENT=1 ORDER BY x.ASSIGNED_DATE DESC,x.ASSIGNMENT_ID DESC)a LEFT JOIN dbo.APP_USER_CACHE au ON au.EMPLOYEE_ID=a.ASSIGNED_TO_EMPLOYEE_ID
 WHERE h.IS_ACTIVE=1 AND EXISTS(SELECT 1 FROM dbo.REQUISITION_ITEM scopeItem JOIN dbo.WORKFLOW_RULE scopeRule ON scopeRule.ASSET_ID=scopeItem.ASSET_ID AND scopeRule.REQ_TYPE=scopeItem.REQ_TYPE AND scopeRule.IS_ACTIVE=1 JOIN dbo.CONCERN_DIVISION_OFFICIAL official ON official.CONCERN_DIVISION_ID=scopeRule.CONCERN_DIVISION_ID AND official.EMPLOYEE_ID=@EmployeeId AND official.IS_ACTIVE=1 AND official.EFFECTIVE_FROM<=CONVERT(DATE,SYSUTCDATETIME())AND(official.EFFECTIVE_TO IS NULL OR official.EFFECTIVE_TO>=CONVERT(DATE,SYSUTCDATETIME()))WHERE scopeItem.REQUISITION_ID=h.REQUISITION_ID AND scopeItem.IS_ACTIVE=1)AND(NULLIF(@RequisitionNo,'')IS NULL OR h.REQUISITION_NO LIKE'%'+@RequisitionNo+'%')AND(NULLIF(@Status,'')IS NULL OR h.CURRENT_STATUS=@Status)AND(@FromDate IS NULL OR CONVERT(DATE,h.REQUESTED_DATE)>=@FromDate)AND(@ToDate IS NULL OR CONVERT(DATE,h.REQUESTED_DATE)<=@ToDate)
 AND(@AssetId IS NULL OR EXISTS(SELECT 1 FROM dbo.REQUISITION_ITEM i WHERE i.REQUISITION_ID=h.REQUISITION_ID AND i.ASSET_ID=@AssetId AND i.IS_ACTIVE=1))AND(NULLIF(@RequisitionType,'')IS NULL OR EXISTS(SELECT 1 FROM dbo.REQUISITION_ITEM i WHERE i.REQUISITION_ID=h.REQUISITION_ID AND i.REQ_TYPE=@RequisitionType AND i.IS_ACTIVE=1))
 ORDER BY h.REQUESTED_DATE DESC;
END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernDivision_GetAllDetail @RequisitionId BIGINT,@EmployeeId VARCHAR(30)
AS BEGIN
 SET NOCOUNT ON;DECLARE @requester VARCHAR(30);
 SELECT @requester=h.REQUESTED_BY_EMPLOYEE_ID FROM dbo.REQUISITION_HEADER h WHERE h.REQUISITION_ID=@RequisitionId AND h.IS_ACTIVE=1 AND EXISTS(SELECT 1 FROM dbo.REQUISITION_ITEM scopeItem JOIN dbo.WORKFLOW_RULE scopeRule ON scopeRule.ASSET_ID=scopeItem.ASSET_ID AND scopeRule.REQ_TYPE=scopeItem.REQ_TYPE AND scopeRule.IS_ACTIVE=1 JOIN dbo.CONCERN_DIVISION_OFFICIAL official ON official.CONCERN_DIVISION_ID=scopeRule.CONCERN_DIVISION_ID AND official.EMPLOYEE_ID=@EmployeeId AND official.IS_ACTIVE=1 AND official.EFFECTIVE_FROM<=CONVERT(DATE,SYSUTCDATETIME())AND(official.EFFECTIVE_TO IS NULL OR official.EFFECTIVE_TO>=CONVERT(DATE,SYSUTCDATETIME()))WHERE scopeItem.REQUISITION_ID=h.REQUISITION_ID AND scopeItem.IS_ACTIVE=1);
 IF @requester IS NULL BEGIN SELECT TOP(0)REQUISITION_ID,REQUISITION_NO,REQUESTED_BY_EMPLOYEE_ID,REQUESTED_ORG_UNIT_ID,CAST(''AS NVARCHAR(200))ORG_UNIT_NAME,REQUESTED_DATE,JUSTIFICATION,TOTAL_ESTIMATED_AMOUNT,CURRENT_STATUS FROM dbo.REQUISITION_HEADER;RETURN;END;
 EXEC dbo.usp_Requisition_GetMakerDetail @RequisitionId,@requester;
END;
GO
